fn run_batch(
    dir: &Path,
    ext: Option<&str>,
    start_nonterminal_id: NonterminalId,
) -> io::Result<()> {
    let use_color = io::stdout().is_terminal();
    let green = if use_color { "\x1b[32m" } else { "" };
    let red = if use_color { "\x1b[31m" } else { "" };
    let reset = if use_color { "\x1b[0m" } else { "" };
    let mut files = Vec::new();
    collect_files(dir, ext, &mut files)?;
    files.sort();
    println!(
        "{:<6}  {:<26}  {:<36}  {}", "STATUS", "TIME (parse, tree)", "REASON", "PATH"
    );
    let mut ok = 0usize;
    let mut failed = 0usize;
    let mut errs = 0usize;
    let mut total_parse_ms: u128 = 0;
    let mut total_tree_ms: u128 = 0;
    let mut max_total_ms: u128 = 0;
    for path in &files {
        let rel = path.strip_prefix(dir).unwrap_or(path.as_path());
        let input = match Input::try_from(path.as_path()) {
            Ok(input) => input,
            Err(e) => {
                errs += 1;
                let reason = format!("IO Error: {}", e);
                println!(
                    "{}{:<6}{}  {:<26}  {:<36}  {}", red, "ERR", reset, "-", reason, rel
                    .display()
                );
                continue;
            }
        };
        let ctx = ParseContext::new();
        let parse_tree_builder = StarParseTreeBuilder::new(&ctx);
        let mut parser = StarParser::new(&input, start_nonterminal_id);
        match parser.run() {
            ParseResult::Success(success) => {
                let parse_ms = success.duration.as_millis();
                let tc_start = Instant::now();
                create_parse_tree(
                    success.sppf_node_id,
                    start_nonterminal_id,
                    &parser,
                    &parse_tree_builder,
                );
                let tree_ms = tc_start.elapsed().as_millis();
                let total_ms = parse_ms + tree_ms;
                ok += 1;
                total_parse_ms += parse_ms;
                total_tree_ms += tree_ms;
                if total_ms > max_total_ms {
                    max_total_ms = total_ms;
                }
                let time = format!("{} ms ({} ms, {} ms)", total_ms, parse_ms, tree_ms);
                println!(
                    "{}{:<6}{}  {:<26}  {:<36}  {}", green, "OK", reset, time, "-", rel
                    .display()
                );
            }
            ParseResult::Failure(error) => {
                let (line, column, _) = parser.format_error(&error);
                failed += 1;
                let reason = format!("Parse Error at line {}, col {}", line, column);
                println!(
                    "{}{:<6}{}  {:<26}  {:<36}  {}", red, "FAIL", reset, "-", reason, rel
                    .display()
                );
            }
        }
    }
    let total_ms = total_parse_ms + total_tree_ms;
    let avg_ms = if ok > 0 { total_ms / ok as u128 } else { 0 };
    println!();
    println!(
        "Parsed {} files: {} OK, {} failed, {} errors", files.len(), ok, failed, errs
    );
    println!(
        "Total {} ms (parse {} ms, tree {} ms); avg {} ms, max {} ms", total_ms,
        total_parse_ms, total_tree_ms, avg_ms, max_total_ms
    );
    Ok(())
}
fn collect_files(
    dir: &Path,
    ext: Option<&str>,
    out: &mut Vec<PathBuf>,
) -> io::Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            collect_files(&path, ext, out)?;
        } else if path.is_file() {
            if let Some(ext_filter) = ext {
                if path.extension().and_then(|e| e.to_str()) != Some(ext_filter) {
                    continue;
                }
            }
            out.push(path);
        }
    }
    Ok(())
}
#[cfg(feature = "debug-trace")]
fn write_trace_events<'i>(
    trace_events: &[TraceEvent],
    parser: &impl Parser<'i>,
    trace_option: &Option<Option<PathBuf>>,
    format: TraceFormat,
) -> io::Result<()> {
    match trace_option {
        Some(Some(path)) => {
            let file = File::create(path)?;
            let mut writer = BufWriter::new(file);
            match format {
                TraceFormat::Text => {
                    for event in trace_events {
                        writeln!(writer, "{}", event.message(parser))?;
                    }
                }
                TraceFormat::Json => {
                    writeln!(
                        writer, "{}", serde_json::to_string(trace_events).unwrap()
                    )?;
                }
            }
        }
        Some(None) => {
            match format {
                TraceFormat::Text => {
                    for event in trace_events {
                        println!("{}", event.message(parser));
                    }
                }
                TraceFormat::Json => {
                    println!("{}", serde_json::to_string(trace_events).unwrap());
                }
            }
        }
        None => {}
    }
    Ok(())
}

